"use client";
/* Boba, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Boba(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("boba"); }, []);
  return React.createElement("piix-sprite", { "name": "boba", ...piixAttrs(props) });
}

export default Boba;
